{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/core",
  "data": [
    {
      "name": "label",
      "type": "string",
      "description": "Label text for the radio group (always rendered for accessibility).",
      "required": true
    },
    {
      "name": "value",
      "type": "string",
      "description": "The currently selected value.",
      "required": true
    },
    {
      "name": "onChange",
      "type": "(value: string) => void",
      "description": "Callback fired when the selected value changes.",
      "required": true
    },
    {
      "name": "children",
      "type": "ReactNode",
      "description": "RadioListItem elements.",
      "slotElements": [
        {
          "__element": "RadioListItem",
          "props": {
            "label": "Option",
            "value": "option"
          }
        }
      ],
      "required": true
    },
    {
      "name": "isLabelHidden",
      "type": "boolean",
      "description": "Whether to visually hide the label.",
      "default": "false"
    },
    {
      "name": "description",
      "type": "string",
      "description": "Description text displayed below the label."
    },
    {
      "name": "orientation",
      "type": "'vertical' | 'horizontal'",
      "description": "Layout direction of the radio items.",
      "default": "'vertical'"
    },
    {
      "name": "isDisabled",
      "type": "boolean",
      "description": "Whether all radio items are disabled.",
      "default": "false"
    },
    {
      "name": "htmlName",
      "type": "string",
      "description": "The HTML name attribute shared by the radio inputs, useful for form submissions. When omitted, a unique internal name still groups the radios."
    },
    {
      "name": "disabledMessage",
      "type": "string",
      "description": "Explains why the group is disabled. Applies to the whole-group disabled state (isDisabled), not per item. With isDisabled, shows a tooltip on hover/keyboard focus and keeps the radios focusable via aria-disabled (selection stays blocked). Use this instead of wrapping a disabled RadioList in Tooltip. Disabled controls swallow the hover events an external Tooltip needs."
    },
    {
      "name": "isRequired",
      "type": "boolean",
      "description": "Whether the radio group is required.",
      "default": "false"
    },
    {
      "name": "isOptional",
      "type": "boolean",
      "description": "Whether the field is optional (mutually exclusive with isRequired).",
      "default": "false"
    },
    {
      "name": "status",
      "type": "{type: 'warning' | 'error' | 'success', message?: string}",
      "description": "Status indicator ({ type, message })."
    },
    {
      "name": "size",
      "type": "'sm' | 'md'",
      "description": "Size of the radio controls.",
      "default": "'md'"
    },
    {
      "name": "labelTooltip",
      "type": "string",
      "description": "Tooltip text for an info icon next to the label."
    },
    {
      "name": "width",
      "type": "SizeValue",
      "description": "Width of the field (number = pixels, string used as-is, e.g. \"100%\"). Sizes the whole field (label, control, and status) so they stay aligned."
    },
    {
      "name": "containerXstyle",
      "type": "StyleXStyles",
      "description": "StyleX styles for the field container (label, control, and status together). No effect inside InputGroup (style the InputGroup instead) or in a `horizontal-labels` FormLayout. Root `xstyle`, `className`, and `style` are not accepted."
    },
    {
      "name": "containerClassName",
      "type": "string",
      "description": "Class name for the field container. Same targeting as `containerXstyle`."
    },
    {
      "name": "containerStyle",
      "type": "CSSProperties",
      "description": "Inline styles for the field container. Same targeting as `containerXstyle`."
    },
    {
      "name": "controlXstyle",
      "type": "StyleXStyles",
      "description": "StyleX styles for the visual control box: the element that paints the border and background and holds icons and end controls. Never the native input."
    },
    {
      "name": "controlClassName",
      "type": "string",
      "description": "Class name for the visual control box."
    },
    {
      "name": "controlStyle",
      "type": "CSSProperties",
      "description": "Inline styles for the visual control box."
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
